import asyncio

# Candidate _drain: await each task; if awaiting it is interrupted by an outer
# cancel, re-cancel THAT task and await it again (shielded) until done.
async def drain(running):
    for t in running:
        while not t.done():
            try:
                await asyncio.shield(t)
            except asyncio.CancelledError:
                if t.done():
                    break
                # outer cancel hit us; ensure this job is cancelled and keep
                # waiting for its cleanup.
                t.cancel()
                # loop again to await it

# Test: with shield, an outer cancel does NOT cancel t via the await (shield
# absorbs), so the ONLY thing that cancels t is our explicit t.cancel().
events=[]
def mk(i):
    async def job():
        try:
            await asyncio.sleep(100)
        except asyncio.CancelledError:
            fut=asyncio.get_event_loop().create_future()
            try:
                await fut
            except asyncio.CancelledError:
                events.append(("done",i)); raise
    return asyncio.ensure_future(job())

async def run(recancel):
    running=[mk(i) for i in range(3)]
    try:
        await asyncio.gather(*running)
    except asyncio.CancelledError:
        for t in running:
            if not t.done(): t.cancel()
        # inline drain to toggle recancel behavior
        for t in running:
            while not t.done():
                try:
                    await asyncio.shield(t)
                except asyncio.CancelledError:
                    if t.done(): break
                    if recancel: t.cancel()
        raise

async def driver(recancel):
    events.clear()
    t=asyncio.ensure_future(run(recancel))
    await asyncio.sleep(0.1); t.cancel()
    await asyncio.sleep(0.05); t.cancel()
    await asyncio.sleep(0.3)
    return t.done(), sorted(events,key=str)

for rc in (True, False):
    d=asyncio.run(driver(rc))
    print(f"recancel={rc}: done={d[0]} events={d[1]}")
EOF
